import { NextFunction, Request, Response } from 'express';
import { DomainError, DomainErrorKind } from '../../domain/errors/DomainError';
import { BadRequestError } from './requestParsing';

const STATUS_BY_KIND: Record<DomainErrorKind, number> = {
  validation: 400,
  'not-found': 404,
  conflict: 409,
};

/** Express rejects malformed JSON with an error carrying a 4xx status. */
function clientStatusOf(err: unknown): number | undefined {
  if (typeof err === 'object' && err !== null && 'status' in err) {
    const status = (err as { status: unknown }).status;
    if (typeof status === 'number' && status >= 400 && status < 500) {
      return status;
    }
  }
  return undefined;
}

export function errorMiddleware(err: unknown, _req: Request, res: Response, _next: NextFunction): void {
  if (err instanceof DomainError) {
    res.status(STATUS_BY_KIND[err.kind]).json({ error: err.message });
    return;
  }
  if (err instanceof BadRequestError) {
    res.status(400).json({ error: err.message });
    return;
  }
  const clientStatus = clientStatusOf(err);
  if (clientStatus !== undefined) {
    res.status(clientStatus).json({ error: 'Malformed request' });
    return;
  }
  console.error(err);
  res.status(500).json({ error: 'Internal server error' });
}

export function notFoundMiddleware(_req: Request, res: Response): void {
  res.status(404).json({ error: 'Route not found' });
}

